mapper.update:
update ${database.prefix.order}hou_order_goods
set order_shipping_code    = #{orderShippingCode},
    order_shipping_message = #{orderShippingMessage}
where order_goods_id = #{orderGoodsId}

update ${database.prefix.order}hou_order_goods
set order_shipping_code       = #{orderShippingCode},
    order_shipping_express_id = #{orderShippingExpressId},
    order_shipping_message    = #{orderShippingMessage}
where order_goods_id = #{orderGoodsId}

update ${database.prefix.order}hou_order_goods
set jd_son_order_id = #{param.jdOrderId}
where jd_order_id = #{param.parentJdOrderId} and goods_id = #{param.goodsId}

mapper.select:
select sum(order_goods_num)
FROM ${database.prefix.order}hou_order_goods
where buyer_user_id = #{param.userId}

    and common_id = #{param.commonId}


    and goods_id = #{param.goodsId}


    and goods_promotion_id = #{param.seckillId}


    and order_goods_time between #{param.goodsStartTime} and #{param.goodsEndTime}

  and order_goods_status != 7

SELECT count(1)
FROM ${database.prefix.business}hou_shop_gate_goods_base
where shop_gate_id = #{shopId}
  and common_id = #{commonId}

select cat_commission
from ${database.prefix.goods}hou_goods_cat
where cat_id = #{catId}

select order_goods_num
FROM ${database.prefix.order}hou_order_goods og
where og.order_id = #{orderId}
  and og.goods_id = #{goodsId}

select goods_price, order_goods_num, order_rpt_price, voucher_price
FROM ${database.prefix.order}hou_order_goods
where order_id = #{orderId}
  and goods_id = #{goodsId}

select oog.common_id,oog.goods_id,oog.goods_image,oog.goods_name,oog.order_goods_amount, oog.goods_price,oog.order_goods_num,oog.order_spec_chineseValue,oog.goods_return_status, oog.goods_refund_status,oog.shipping_fee,oog.order_goods_payment_amount,oog.order_goods_returnnum, oob.order_payment_amount,oob.order_shipping_fee,sb.shop_name,oob.order_id,oob.order_create_time FROM ${database.prefix.order}hou_order_goods oog left join ${database.prefix.order}hou_order_base oob on oob.order_id = oog.order_id left join ${database.prefix.supplier}hou_shop_base sb on sb.supplier_shop_id = oob.shop_id where oog.order_id = #{param.orderId}
and oog.goods_id in
#{id}

select order_goods_payment_amount
from ${database.prefix.order}hou_order_goods
where goods_id = #{goodsId}
  and order_id = #{orderId}

select giveaway_info
FROM ${database.prefix.order}hou_order_base
where order_id = #{param}

select sum(oog.order_goods_num)
FROM ${database.prefix.order}hou_order_goods oog
         left join ${database.prefix.order}hou_order_base oob on oob.order_id = oog.order_id
where oog.buyer_user_id = #{userId}
  and oog.goods_id = #{goodsId}
  and oob.order_status != 7

select sum(order_goods_num)
FROM ${database.prefix.order}hou_order_goods
where buyer_user_id = #{param.userId}
  and common_id = #{param.commonId}
  and goods_promotion_id = #{param.discountId}
  and order_goods_time between #{param.fDate} and now()
  and order_goods_status != 7

select sum(order_goods_commission) FROM ${database.prefix.order}hou_order_goods where order_id = #{orderId}
and goods_id not in (

    #{goods.goodsId}

)

select goods_id as goodsId, common_id as commonId, order_goods_num as goodsNum
FROM ${database.prefix.order}hou_order_goods
where order_id = #{orderId}

select common_id, goods_id, order_goods_returnnum, order_goods_num
FROM ${database.prefix.order}hou_order_goods og
where og.order_id = #{orderId}

select sum(order_goods_num) FROM ${database.prefix.order}hou_order_goods
where buyer_user_id = #{param.userId} and common_id = #{param.commonId}
  and order_goods_time >= #{param.fDate}
  and order_goods_status != 7
  and goods_promotion_id = #{param.discountId}


select count(1)
FROM ${database.prefix.order}hou_order_goods
where buyer_user_id = #{param.userId} and order_goods_time < #{param.endDateTime} and shop_id = #{param.shopId}

        select count(1) from (
                                 select distinct order_id
                                 FROM ${database.prefix.order}hou_order_goods
                                 where order_goods_status not in (1, 7)
                                   and goods_return_status != 2
								   and goods_refund_status != 2
								   and goods_id =#{param.goodsId} and goods_price =#{param.discountPrice}
                                   and order_goods_time between #{param.endDateTime} and #{param.startDateTime}
                                   and buyer_user_id = #{param.userId}
                             ) as a

select oog.order_goods_returnnum as goodsNum, oog.barter_goods_id as goodsId, oog.common_id FROM ${database.prefix.order}hou_order_goods oog where oog.order_id = #{param.orderId} and (oog.goods_return_status != 0 or oog.goods_refund_status != 0 or oog.goods_barter_status != 0)
and order_barter_id in
#{orderBarterId}
